<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { BookOpen, Users, LogOut, Pencil, Trash2, UserRound, RefreshCw, Search, ChevronLeft, ChevronRight } from '@lucide/vue'
import { useAuthStore } from '../../../stores/auth.store'
import { createApiClient } from '../../../services/api-client'
import { friendlyError } from '../../../services/error-handler'
import type { StaffRole } from '../../auth/types'
import type { Story } from '../../library/types'

interface ManagedUser { id: string; displayName: string; email: string; role?: StaffRole; createdAt?: string }
interface Page<T> { items: T[]; page: number; pageSize: number; total: number; totalPages: number }
const route = useRoute(); const router = useRouter(); const authStore = useAuthStore(); const client = createApiClient()
const section = computed<'stories' | 'users'>(() => route.path === '/admin/users' && authStore.user?.role === 'admin' ? 'users' : 'stories')
const stories = ref<Story[]>([]); const users = ref<ManagedUser[]>([]); const loading = ref(false); const error = ref(''); const notice = ref('')
const query = ref(''); const roleFilter = ref(''); const page = ref(1); const total = ref(0); const totalPages = ref(1); const pageSize = 20
const roleBusy = ref(new Set<string>()); const actionBusy = ref(new Set<string>())
const pages = computed(() => { const end=Math.max(1,totalPages.value); const around=[1,end,page.value-1,page.value,page.value+1].filter(n=>n>=1&&n<=end); return [...new Set(around)].sort((a,b)=>a-b) })
const label = computed(() => section.value === 'users' ? 'Người dùng' : 'Truyện')
function apiPage<T>(value: unknown): Page<T> { const p=value as Partial<Page<T>>; return { items:Array.isArray(p.items)?p.items:[], page:Number(p.page)||1, pageSize:Number(p.pageSize)||pageSize, total:Number(p.total)||0, totalPages:Math.max(1,Number(p.totalPages)||1) } }
async function load() {
  loading.value=true; error.value=''; notice.value=''
  try {
    const params=new URLSearchParams({ paginated:'true', page:String(page.value), pageSize:String(pageSize) })
    if(query.value.trim()) params.set('q',query.value.trim()); if(section.value==='users'&&roleFilter.value) params.set('role',roleFilter.value)
    const data=section.value==='users' ? await client.request<Page<ManagedUser>>('/api/admin/users?'+params) : await client.request<Page<Story>>('/api/admin/stories?'+params)
    const result=apiPage(data); total.value=result.total; totalPages.value=result.totalPages; page.value=result.page
    if(section.value==='users') users.value=result.items as ManagedUser[]; else stories.value=result.items as Story[]
  } catch(cause) { error.value=friendlyError(cause) } finally { loading.value=false }
}
let searchTimer: ReturnType<typeof setTimeout>|undefined
watch([section, query, roleFilter], () => { page.value=1; clearTimeout(searchTimer); searchTimer=setTimeout(load, query.value ? 280 : 0) })
watch(page, () => load()); onMounted(load)
function go(target:number) { if(target>=1&&target<=totalPages.value&&target!==page.value) page.value=target }
function openStory(story: Story) { sessionStorage.setItem('moc:editor-motion',JSON.stringify(story)); router.push({path:'/library/editor/'+encodeURIComponent(story.id),query:{from:'admin'}}) }
function busy(set: Set<string>, id:string, value:boolean) { const next=new Set(set); value?next.add(id):next.delete(id); return next }
async function deleteStory(story: Story) { if(!window.confirm(`Xóa truyện “${story.title}”?`)) return; actionBusy.value=busy(actionBusy.value,story.id,true); try { await client.request('/api/stories/'+encodeURIComponent(story.id),{method:'DELETE'}); notice.value='Đã xóa truyện.'; await load() } catch(cause){error.value=friendlyError(cause)} finally{actionBusy.value=busy(actionBusy.value,story.id,false)} }
async function changeRole(user: ManagedUser, role:string) { if(role!==''&&role!=='admin'&&role!=='moderator') return; const old=user.role||''; if(old===role)return; if(user.id===authStore.user?.id){error.value='Tài khoản đang đăng nhập không thể tự đổi quyền.';return}; roleBusy.value=busy(roleBusy.value,user.id,true); try { await client.request('/api/admin/users/'+encodeURIComponent(user.id)+'/role',{method:'PUT',body:JSON.stringify({role})}); user.role=role as StaffRole||undefined; notice.value='Đã cập nhật quyền.' } catch(cause){error.value=friendlyError(cause)} finally{roleBusy.value=busy(roleBusy.value,user.id,false)} }
async function deleteUser(user: ManagedUser) { if(user.id===authStore.user?.id)return; if(!window.confirm(`Xóa tài khoản ${user.email}? Dữ liệu truyện của tài khoản cũng sẽ bị xóa.`))return; actionBusy.value=busy(actionBusy.value,user.id,true); try { await client.request('/api/admin/users/'+encodeURIComponent(user.id),{method:'DELETE'}); notice.value='Đã xóa người dùng.'; await load() } catch(cause){error.value=friendlyError(cause)} finally{actionBusy.value=busy(actionBusy.value,user.id,false)} }
async function logout(){await authStore.logout();router.replace('/admin/login')}
function roleName(role?:StaffRole){return role==='admin'?'Admin':role==='moderator'?'Moderator':'Người dùng'}
function statusName(status?:string){return status==='completed'?'Hoàn thành':status==='draft'?'Bản nháp':'Đang ra'}
function date(value?:string){return value?new Intl.DateTimeFormat('vi-VN',{dateStyle:'medium'}).format(new Date(value)):'—'}
</script>

<template>
  <div class="admin-shell">
    <aside class="admin-sidebar" aria-label="Khu vực quản trị">
      <div class="admin-sidebar-top"><span class="admin-sidebar-kicker">MOC</span><span class="admin-sidebar-title">Quản trị</span></div>
      <nav class="admin-nav">
        <button type="button" :class="{active:section==='stories'}" @click="router.push('/admin')"><BookOpen :size="18"/><span>Truyện</span></button>
        <button v-if="authStore.user?.role==='admin'" type="button" :class="{active:section==='users'}" @click="router.push('/admin/users')"><Users :size="18"/><span>Người dùng</span></button>
      </nav>
      <div class="admin-sidebar-account"><div class="admin-user"><UserRound :size="17"/><span><strong>{{ authStore.user?.displayName }}</strong><small>{{ roleName(authStore.user?.role) }}</small></span></div><button class="admin-logout" type="button" @click="logout"><LogOut :size="17"/><span>Đăng xuất</span></button></div>
    </aside>
    <main class="admin-main" aria-label="Nội dung quản trị">
      <div class="admin-heading"><div><p class="admin-kicker">Quản trị nội dung</p><h1>{{ label }}</h1></div><button class="admin-refresh" type="button" :disabled="loading" aria-label="Tải lại" @click="load"><RefreshCw :size="17" :class="{spin:loading}"/></button></div>
      <div class="admin-toolbar"><label class="admin-search"><Search :size="17"/><span class="sr-only">Tìm kiếm</span><input v-model="query" type="search" :placeholder="section==='users'?'Tìm tên hoặc email':'Tìm tiêu đề hoặc tác giả'"/></label><select v-if="section==='users'" v-model="roleFilter" aria-label="Lọc theo quyền"><option value="">Tất cả quyền</option><option value="admin">Admin</option><option value="moderator">Moderator</option></select><span class="admin-total">{{ total }} {{ section==='users'?'người dùng':'truyện' }}</span></div>
      <p v-if="error" class="admin-message error" role="alert">{{ error }}</p><p v-if="notice" class="admin-message success" role="status">{{ notice }}</p>
      <div class="admin-table-wrap" aria-live="polite">
        <table v-if="section==='users'" class="admin-table"><caption class="sr-only">Danh sách người dùng</caption><thead><tr><th>Người dùng</th><th>Email</th><th>Quyền</th><th>Ngày tạo</th><th><span class="sr-only">Thao tác</span></th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><div class="identity"><span class="identity-icon"><UserRound :size="16"/></span><strong>{{ user.displayName }}</strong></div></td><td class="muted">{{ user.email }}</td><td><select :value="user.role||''" :disabled="roleBusy.has(user.id)||user.id===authStore.user?.id" :aria-label="'Quyền của '+user.displayName" @change="changeRole(user,($event.target as HTMLSelectElement).value)"><option value="">Người dùng</option><option value="moderator">Moderator</option><option value="admin">Admin</option></select></td><td class="muted">{{ date(user.createdAt) }}</td><td class="actions"><button type="button" :disabled="actionBusy.has(user.id)||user.id===authStore.user?.id" aria-label="Xóa người dùng" @click="deleteUser(user)"><Trash2 :size="16"/></button></td></tr></tbody></table>
        <table v-else class="admin-table"><caption class="sr-only">Danh sách truyện</caption><thead><tr><th>Truyện</th><th>Tác giả</th><th>Trạng thái</th><th>Chương</th><th>Cập nhật</th><th><span class="sr-only">Thao tác</span></th></tr></thead><tbody><tr v-for="story in stories" :key="story.id"><td><button class="story-link" type="button" @click="openStory(story)">{{ story.title }}</button></td><td class="muted">{{ story.authorName||'—' }}</td><td><span class="status" :data-status="story.status">{{ statusName(story.status) }}</span></td><td class="muted">{{ story.chapterCount||0 }}</td><td class="muted">{{ date(story.updatedAt) }}</td><td class="actions"><button type="button" aria-label="Sửa truyện" @click="openStory(story)"><Pencil :size="16"/></button><button type="button" :disabled="actionBusy.has(story.id)" aria-label="Xóa truyện" @click="deleteStory(story)"><Trash2 :size="16"/></button></td></tr></tbody></table>
        <div v-if="loading" class="admin-state">Đang tải dữ liệu</div><div v-else-if="!users.length && section==='users'" class="admin-state">Không có người dùng phù hợp.</div><div v-else-if="!stories.length && section==='stories'" class="admin-state">Không có truyện phù hợp.</div>
      </div>
      <nav v-if="totalPages>1" class="pagination" aria-label="Phân trang"><button type="button" :disabled="page===1" aria-label="Trang trước" @click="go(page-1)"><ChevronLeft :size="17"/></button><template v-for="(number,index) in pages" :key="number"><span v-if="index&&number-pages[index-1]>1" class="ellipsis">…</span><button type="button" :class="{current:number===page}" :aria-current="number===page?'page':undefined" @click="go(number)">{{ number }}</button></template><button type="button" :disabled="page===totalPages" aria-label="Trang sau" @click="go(page+1)"><ChevronRight :size="17"/></button></nav>
    </main>
  </div>
</template>

<style scoped>
.admin-shell{height:100dvh;display:flex;overflow:hidden;background:#f5f6f0;color:#29392a}.admin-sidebar{width:224px;flex:0 0 224px;display:flex;flex-direction:column;min-height:0;padding:28px 16px;background:#e9eee4}.admin-sidebar-top{display:flex;align-items:baseline;gap:10px;padding:0 12px 34px}.admin-sidebar-kicker,.admin-kicker{color:#70806c;font-size:10px;letter-spacing:.12em;text-transform:uppercase}.admin-sidebar-title{font:400 20px var(--serif)}.admin-nav{display:grid;gap:4px}.admin-nav button,.admin-logout{display:flex;align-items:center;gap:11px;width:100%;padding:12px;border:0;color:#647262;background:transparent;font:500 12px var(--sans);text-align:left;cursor:pointer}.admin-nav button.active{color:#f7faf3;background:#435a41}.admin-sidebar-account{margin-top:auto;padding-top:20px}.admin-user{display:flex;align-items:center;gap:10px;padding:12px;color:#536252}.admin-user span{min-width:0;display:grid;gap:3px}.admin-user strong{overflow:hidden;font-size:12px;text-overflow:ellipsis;white-space:nowrap}.admin-user small{font-size:10px;color:#778576}.admin-logout{color:#8c5047}.admin-main{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;padding:42px clamp(22px,5vw,72px);overflow:hidden}.admin-heading{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:28px}.admin-heading h1{margin:5px 0 0;font:400 32px/1 var(--serif);letter-spacing:-.03em}.admin-kicker{margin:0}.admin-refresh{display:grid;place-items:center;width:38px;height:38px;border:0;color:#60705e;background:#e6ece1;cursor:pointer}.admin-refresh:disabled{opacity:.55}.spin{animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.admin-toolbar{display:flex;align-items:center;gap:12px;margin-bottom:14px}.admin-search{display:flex;align-items:center;gap:9px;flex:1;min-width:160px;padding:0 13px;color:#6c796a;background:#e8eee3}.admin-search input{width:100%;min-height:42px;border:0;outline:0;color:#29392a;background:transparent}.admin-toolbar select,.admin-table select{min-height:36px;padding:0 10px;border:0;color:#526352;background:#e8eee3;font:500 11px var(--sans)}.admin-total{color:#788576;font-size:11px;white-space:nowrap}.admin-message{margin:0 0 12px;padding:10px 12px;font-size:12px}.admin-message.error{color:#8b3d35;background:#f5e6df}.admin-message.success{color:#557052;background:#e5eee1}.admin-table-wrap{flex:1;min-height:0;overflow:auto;background:#fbfcf7}.admin-table{width:100%;min-width:700px;border-collapse:collapse;table-layout:auto}.admin-table th,.admin-table td{padding:14px 16px;border:0;text-align:left;font-size:12px;vertical-align:middle}.admin-table th{position:sticky;top:0;z-index:1;color:#778475;background:#fbfcf7;font-size:10px;font-weight:600;letter-spacing:.05em;text-transform:uppercase}.admin-table tbody tr{background:#fbfcf7}.admin-table tbody tr+tr td{padding-top:10px}.identity{display:flex;align-items:center;gap:10px;min-width:160px}.identity-icon{display:grid;place-items:center;width:30px;height:30px;color:#546951;background:#e4ebe0}.muted{color:#738073}.story-link{max-width:270px;padding:0;border:0;overflow:hidden;color:#304731;background:transparent;font:650 12px var(--sans);text-align:left;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}.story-link:hover{color:#557552;text-decoration:underline;text-underline-offset:3px}.status{display:inline-block;padding:5px 8px;color:#60735d;background:#edf2ea;font-size:10px;white-space:nowrap}.status[data-status=draft]{color:#8c6a36;background:#f4ecdb}.status[data-status=completed]{color:#486b58;background:#e3eee6}.actions{width:92px;white-space:nowrap}.actions button{display:inline-grid;place-items:center;width:32px;height:32px;margin-left:3px;border:0;color:#6f7d6d;background:transparent;cursor:pointer}.actions button:hover{color:#29392a;background:#e6ece1}.actions button:last-child{color:#985049}.actions button:disabled{opacity:.4;cursor:not-allowed}.admin-state{padding:52px;color:#778275;font-size:12px;text-align:center}.pagination{display:flex;justify-content:center;align-items:center;gap:4px;padding-top:18px}.pagination button{display:grid;place-items:center;min-width:32px;height:32px;padding:0 8px;border:0;color:#687665;background:transparent;font-size:12px;cursor:pointer}.pagination button.current{color:#f7faf3;background:#435a41}.pagination button:disabled{opacity:.35;cursor:not-allowed}.ellipsis{padding:0 3px;color:#8b9687}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}@media(max-width:700px){.admin-shell{overflow:hidden}.admin-sidebar{width:62px;flex-basis:62px;padding:22px 8px}.admin-sidebar-top{padding:0 8px 30px}.admin-sidebar-title,.admin-sidebar-account span,.admin-nav button span{display:none}.admin-nav button,.admin-logout{justify-content:center;padding:11px}.admin-user{justify-content:center;padding:11px 0}.admin-main{padding:28px 14px}.admin-heading h1{font-size:28px}.admin-total{display:none}.admin-table th,.admin-table td{padding:12px 10px}.admin-table-wrap{margin:0 -14px;padding:0 14px}}
</style>

